/* PR middle-end/53084 */

extern void abort(void);

__attribute__((noinline, noclone)) void bar(const char *p) {
  if (p[0] != 'o' || p[1] != 'o' || p[2])
    abort();
}

int main() {
  static const char *const foo[] = {"foo" + 1};
  bar(foo[0]);
  return 0;
}


